update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 10: Verantwortliche Parteien und Zuständigkeiten | Betreiber der weitergehenden Aufbereitungseinrichtung (der personenidentisch mit dem Betreiber der kommunalen Kläranlage sein kann, aber nicht muss) | Federführung bei der Erstellung des RMP nach Artikel 5 Absatz 2 EU-Wasser-WVVO und verantwortlich für dessen Fortschreibung | Die Aufbereitungsgenehmigung muss gemäß § 61b WHG (siehe Referentenentwurf BMUV 2024) mindestens den Vorgang der weitergehenden Aufbereitung umfassen [...] Antragsteller ist der Betreiber der Aufbereitungseinrichtung. — printed p.49 / p.84', verification_note='md-verified 2026-09-05 (Tab. 10 §6.2.2; §7.2, printed p.49 / p.84 derived) [VC]', verified_at=now() where id='f4b3a6a0-a62f-4b71-8848-3e6c8c879b13' and verification_status not in ('verified_against_standard','corrected');
