update public.fields set verification_status='verified_against_standard', verification_quote='Aufbereitetes Wasser | kommunales Abwasser, das gemäß den Anforderungen der Richtlinie 91/271/EWG behandelt wurde und in einer Aufbereitungseinrichtung gemäß Anhang I Abschnitt 2 der Verordnung (EU) 2020/741 weiterbehandelt wurde (Quelle: Verordnung (EU) 2020/741, EU-WasserWVVO) | Nach der EU-WasserWVVO erfolgt die Wiederverwendung von aufbereitetem Wasser in bis zu fünf Stufen: 1. Kommunales Abwasser wird in einer dafür zugelassenen Abwasserbehandlungsanlage (Kläranlage) behandelt. | 4. Beschreibung der bestehenden Kläranlage mit Ablaufqualität und -mengen: Definiert durch installierte Behandlungsprozesse — printed p.12 / p.44 / p.46', verification_note='md-verified 2026-09-05 (§2.1 definition; §6.2.1.2; §6.2.1.3 Kernelement 4, printed p.12 / p.44 / p.46 derived) [VC]', verified_at=now() where id='232b73dd-2a00-4460-8f2f-8f5df8ac7e77' and verification_status not in ('verified_against_standard','corrected');
