-- ######################## M12001-02 · Anwendbarkeit und Systemabgrenzung ########################
-- heilquellenschutzgebiet
update public.fields set verification_status='verified_against_standard', verification_quote='Trinkwasserversorger | Der Trinkwasserversorger ist bei der Erstellung des RMP zu beteiligen, wenn Anwendungen in einem Trinkwassereinzugs-/Wasserschutzgebiet vorgesehen sind. Eine Aufbringung von aufbereitetem Wasser in Wasserschutzgebietszonen I und II und Heilquellenschutzgebieten ist entsprechend § 61a Absatz 1 WHG (BMUV 2024) ausgeschlossen. Darüber hinaus können Bundesländer durch Rechtsverordnung Flussgebietseinheiten oder Teile davon festlegen, in denen die Wasserwiederverwendung zur landwirtschaftlichen Bewässerung nicht angebracht ist. — printed p.52', verification_note='md-verified 2026-09-05 (§6.2.2 "Trinkwasserversorger", printed p.52 derived — between Tab. 11 p.51 and Tab. 12 p.52) [VC]', verified_at=now() where id='ebff75c5-4cc0-4fa6-b736-ba86da6ea7ec' and verification_status not in ('verified_against_standard','corrected');
-- industrielle_reuse
update public.fields set verification_status='verified_against_standard', verification_quote='Die Wiederverwendung von aufbereitetem Wasser aus kommunalen Kläranlagen als Brauchwasser für industrielle Anwendungen wird in diesem Merkblatt nicht betrachtet, da je nach Branche und Anwendungszweck unterschiedliche Ansprüche hinsichtlich der Wasserqualität zu erfüllen sind. Die dargestellte Herangehensweise bzgl. des Risikomanagements im Zusammenhang mit Wasserwiederverwendung ist jedoch auf derartige und weitere Anwendungen sowie aufbereitete Wässer anderer Herkunft grundsätzlich übertragbar. | Nicht betrachtet wird die Wiederverwendung industrieller und gewerblicher Abwässer, zum Beispiel im Zuge der industriellen Kreislaufführung. — printed p.11', verification_note='md-verified 2026-09-05 (§1 Anwendungsbereich, printed p.11 derived) [VC]', verified_at=now() where id='b5837d74-8abf-413e-87c9-48270ea65641' and verification_status not in ('verified_against_standard','corrected');
-- schutzzone_status
update public.fields set verification_status='verified_against_standard', verification_quote='Demnach ist eine Wasserwiederverwendung in Wasserschutzgebieten der Schutzzonen I und II nicht zulässig. Weitere Gebietsausschlüsse können durch die Bundesländer entsprechend Artikel 2 Absatz 2 der EU-WasserWVVO geregelt werden. | Schutzgebiete | Eine Aufbringung von aufbereitetem Wasser in Wasserschutzgebietszonen I und II ist entsprechend § 61a WHG ausgeschlossen. Unter bestimmten Voraussetzungen kann eine Wasserwiederverwendung in der Schutzzone III genehmigt werden. In diesen Fällen wird zur Sicherung der Trinkwassergewinnung abhängig von der Exposition (siehe Tabelle 16) ein zusätzliches Monitoring empfohlen. — printed p.33 / p.62', verification_note='md-verified 2026-09-05 (§5.2; §6.3.2.2 "Schutzgebiete", printed p.33 / p.62 derived) [VC] — Zone III is conditionally permissible; the field only captures I/II', verified_at=now() where id='341cb3f0-319d-42d5-9962-c3b9e601a33d' and verification_status not in ('verified_against_standard','corrected');


