update public.fields set verification_status='verified_against_standard', verification_quote='Ist der ökologisch erforderliche Mindestabfluss des aufnehmenden Gewässers in Trockenphasen beeinträchtigt, und ist eine Beeinträchtigung durch eine Verringerung der Klarwassereinleitung zu befürchten? (siehe Revision WHG 2025) | Entsprechend § 61b WHG (siehe Referentenentwurf BMUV 2024) ist eine Genehmigung voraussichtlich zu versagen, wenn die Wasserwiederverwendung dazu führt, dass in einem oberirdischen Gewässer durch die reduzierte oder ausbleibende Klarwassereinleitung die Mindestwasserführung nach § 33 nicht erhalten bleibt. Dieser Sachverhalt ist im RMP entsprechend auszuführen. — printed p.45 / p.85', verification_note='md-verified 2026-09-05 (§6.2.1.3 Leitfragen zur Vulnerabilität; §7.2, printed p.45 / p.85 derived) [VC]', verified_at=now() where id='77585e4a-bba9-4c08-9b97-e7d52e3bf887' and verification_status not in ('verified_against_standard','corrected');
