update public.fields set verification_status='verified_against_standard', verification_quote='RMP-Team | Der RMP für die Wasserwiederverwendung wird federführend vom Betreiber der Aufbereitungseinrichtung zusammen mit den anderen verantwortlichen Akteuren vorbereitet. Für die Erstellung wird ein RMP-Team eingesetzt, das für die Entwicklung und Umsetzung des RMP sowie die Erstellung eines Zeitplans verantwortlich ist. Die Mitglieder des RMP-Teams müssen über ausreichende Fachkenntnisse und Praxiserfahrungen verfügen. Ein handlungsfähiges und engagiertes RMP-Team ist die Grundvoraussetzung für die erfolgreiche Umsetzung eines RMP. — printed p.41', verification_note='md-verified 2026-09-05 (§6.1 "RMP-Team", printed p.41 derived) [VC]', verified_at=now() where id='7bf8c849-6107-486c-b35c-7d33a67537b1' and verification_status not in ('verified_against_standard','corrected');
