-- ######################## M12001-05 · Schutzgüter und Expositionswege (KRM 3) ########################
-- schutzgut_mensch_betroffen
update public.fields set verification_status='verified_against_standard', verification_quote='Bei einer Bewässerung landwirtschaftlicher und urbaner Flächen sowie sonstiger Anwendungen mit aufbereitetem Wasser muss das Risiko negativer Auswirkungen auf folgende Schutzgüter minimiert werden: | Menschen als Abnehmer*innen und Konsumierende bewässerter Erzeugnisse, als Personal in städtischen, landwirtschaftlichen oder verarbeitenden Betrieben und als anwohnende Personen oder sonstige Nutzende von bewässerten Flächen, — printed p.53', verification_note='md-verified 2026-09-05 (§6.3.2.1 Schutzgüter list, printed p.53 derived) [VC]', verified_at=now() where id='e811a1ed-482a-4632-882d-686b5131c679' and verification_status not in ('verified_against_standard','corrected');
-- schutzgut_wasserressourcen
update public.fields set verification_status='verified_against_standard', verification_quote='Bei einer Bewässerung landwirtschaftlicher und urbaner Flächen sowie sonstiger Anwendungen mit aufbereitetem Wasser muss das Risiko negativer Auswirkungen auf folgende Schutzgüter minimiert werden: | Wasserressourcen, d. h. Grundwasser, Oberflächengewässer und Küstengewässer einschließlich der dort vorkommenden Biota, | Explizit zu berücksichtigen sind dabei Wasserressourcen, die für die Trinkwasserversorgung genutzt werden, Ökosysteme und/oder Schutzgebiete sowie nährstoffsensible und in Bezug auf Nitratbelastung gefährdete Gebiete in der Nähe des Wasserwiederverwendungssystems. — printed p.53', verification_note='md-verified 2026-09-05 (§6.3.2.1 Schutzgüter list, printed p.53 derived) [VC]', verified_at=now() where id='27cf4621-aada-44e1-8019-7c6401b10893' and verification_status not in ('verified_against_standard','corrected');
-- schutzgut_boden
update public.fields set verification_status='verified_against_standard', verification_quote='Bei einer Bewässerung landwirtschaftlicher und urbaner Flächen sowie sonstiger Anwendungen mit aufbereitetem Wasser muss das Risiko negativer Auswirkungen auf folgende Schutzgüter minimiert werden: | Böden der bewässerten Flächen, | Bodenvorsorge | Die Aufbringung von aufbereitetem Wasser fällt grundsätzlich unter die allgemeine Vorsorgepflicht des § 7 BBodSchG. — printed p.53 / p.28', verification_note='md-verified 2026-09-05 (§6.3.2.1 Schutzgüter list; §4.5 "Bodenvorsorge", printed p.53 / p.28 derived) [VC]', verified_at=now() where id='f5e407f7-e260-4822-a922-ef731ed70f38' and verification_status not in ('verified_against_standard','corrected');
-- schutzgut_pflanzen
update public.fields set verification_status='verified_against_standard', verification_quote='Bei einer Bewässerung landwirtschaftlicher und urbaner Flächen sowie sonstiger Anwendungen mit aufbereitetem Wasser muss das Risiko negativer Auswirkungen auf folgende Schutzgüter minimiert werden: | die bewässerten Anbaukulturen (Nahrungsmittel, Futtermittel, Energiepflanzen) oder urbane Grünflächen (Wiesen, Parkflächen mit Blühpflanzen, ggf. Sportflächen), — printed p.53', verification_note='md-verified 2026-09-05 (§6.3.2.1 Schutzgüter list, printed p.53 derived) [VC]', verified_at=now() where id='cdae9f2c-ed23-48e7-80c8-a29caaba0d21' and verification_status not in ('verified_against_standard','corrected');
-- schutzgut_tiere
update public.fields set verification_status='verified_against_standard', verification_quote='Bei einer Bewässerung landwirtschaftlicher und urbaner Flächen sowie sonstiger Anwendungen mit aufbereitetem Wasser muss das Risiko negativer Auswirkungen auf folgende Schutzgüter minimiert werden: | Tiere, deren Weideflächen oder Futtermittel mit aufbereitetem Wasser bewässert wurden, sowie Wildtiere. — printed p.53', verification_note='md-verified 2026-09-05 (§6.3.2.1 Schutzgüter list, printed p.53 derived) [VC]', verified_at=now() where id='01737501-8fe9-4632-9b4e-405e4184748d' and verification_status not in ('verified_against_standard','corrected');
-- expositionsweg_1_relevant
update public.fields set verification_status='verified_against_standard', verification_quote='Im Folgenden werden mögliche Risiken für Schutzgüter beispielhaft anhand von drei Expositionswegen erörtert und mit typischen Elementen dargestellt, die bei der Wasserwiederverwendung voraussichtlich relevant sind: 1. Exposition über die landwirtschaftlichen Erzeugnisse, | Expositionsweg 1: Landwirtschaftliche Erzeugnisse (Wasser - Pflanze - (Tier -) Mensch) | Für die Wasserwiederverwendung in der Landwirtschaft besonders relevant ist der sichere Konsum der landwirtschaftlichen Produkte und damit der Expositionsweg „Wasser - Pflanze - (Tier -) Mensch“ (siehe Tabelle 13). — printed p.53–54', verification_note='md-verified 2026-09-05 (§6.3.2.1 "Expositionsweg 1" + Tab. 13 p.55, printed p.53–54 derived) [VC]', verified_at=now() where id='b89a72dd-ddac-49f6-b10e-69b036fc682a' and verification_status not in ('verified_against_standard','corrected');
-- expositionsweg_2_relevant
update public.fields set verification_status='verified_against_standard', verification_quote='Expositionsweg 2: Direkter Wasserkontakt (Wasser - Mensch) | Der direkte Wasserkontakt von Menschen bei der Bewässerung und damit der Expositionsweg „Wasser - (Luft -) Mensch" kann Gesundheitsrisiken bergen: Arbeitende, Nutzende der Flächen oder Anrainer könnten in Kontakt mit Bewässerungswasser kommen (siehe Tabelle 14). Spritzwasser und | Aerosole können sich vor allem beim Verregnen und bei starkem Wind in der direkten Umgebung verbreiten. Die Exposition von Menschen kann zum Beispiel durch Zugangsbeschränkungen und eine an die Windverhältnisse angepasste Bewässerung vermieden werden. — printed p.55–56', verification_note='md-verified 2026-09-05 (§6.3.2.1 "Expositionsweg 2" + Tab. 14 p.56, printed p.55–56 derived) [VC]', verified_at=now() where id='76be4025-8e72-4d69-9aed-c3b4a2f5d05e' and verification_status not in ('verified_against_standard','corrected');
-- expositionsweg_3_relevant
update public.fields set verification_status='verified_against_standard', verification_quote='Expositionsweg 3: Boden und Grundwasser/Oberflächengewässer (Wasser - Boden - Grundwasser/Oberflächengewässer - Mensch) | Der Bodenkontakt von Bewässerungswasser ist nicht vermeidbar und bringt das Risiko mit sich, dass gegebenenfalls enthaltene Kontaminanten des Bewässerungswassers oder zum Beispiel Salze in die Bodenmatrix übergehen. | Für den Expositionsweg „Boden - Grundwasser/Oberflächengewässer“ sind folgende mögliche Bedingungen relevant: Große Mengen an Bewässerungswasser können zu einem erhöhten Eintrag von Schadstoffen führen. Dies ist durch bedarfsgerechte Bewässerung zu minimieren. — printed p.57', verification_note='md-verified 2026-09-05 (§6.3.2.1 "Expositionsweg 3" + Tab. 15 p.58, printed p.57 derived) [VC]', verified_at=now() where id='fc5e1a0d-e2ae-4bc9-b3d9-c1d95b4101f2' and verification_status not in ('verified_against_standard','corrected');


-- ######################## M12001-06 · Gefahrenanalyse (KRM 4) ########################
-- aerosolrisiko
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 8：Arbeitshilfe A：Mindestanforderungen an die Qualität von aufbereitetem Wasser für die landwirtschaftliche und urbane Wasserwiederverwendung sowie Leistungsziele für Aufbereitungs－ einrichtungen in Deutschland | Fallspezifische Anforderungen | Legionella spp．： $<1.000 \mathrm{KBE} / \mathrm{L}$ ， wenn das Risiko der Aerosol－ bildung besteht； | Tabelle 27: Mindesthäufigkeit der Routineüberwachung von aufbereitetem Wasser | Legionella spp. (falls zutreffend) — printed p.39 / p.80', verification_note='md-verified 2026-09-05 (Tab. 8 "Fallspezifische Anforderungen"; Tab. 27 header, printed p.39 / p.80 derived) [VC] — Tab. 8 md uses fullwidth punctuation, copied verbatim', verified_at=now() where id='c3bff6ea-2b95-4b59-9abd-10026a39b47d' and verification_status not in ('verified_against_standard','corrected');
-- gefahr_mikrobiologisch
update public.fields set verification_status='verified_against_standard', verification_quote='Von den verschiedenen Krankheitserregern, die im kommunalen Abwasser auftreten können, werden in der EU-WasserWVVO folgende Gruppen berücksichtigt: Bakterien, Viren, Protozoen und Helminthen. | Dabei ist zu unterscheiden zwischen Gefahren durch mikrobiologische und chemische Wasserinhaltsstoffe sowie Gefahren durch gefährliche Ereignisse und Störfälle. | Gefahren durch mikrobiologische Pathogene | Gefahren durch mikrobiologische Pathogene werden durch den Nachweis einer adäquaten Aufbereitung (d. h. Einhaltung von Leistungszielen bei der Validierung sowie chemisch-physikalischen Parametern im Regelbetrieb) minimiert. — printed p.21 / p.64', verification_note='md-verified 2026-09-05 (§4.2.2; §6.3.3, printed p.21 / p.64 derived) [VC]', verified_at=now() where id='b629df87-8b49-4e8a-9b73-c6e91b5c3c54' and verification_status not in ('verified_against_standard','corrected');
-- gefahr_schwermetalle
update public.fields set verification_status='verified_against_standard', verification_quote='Allerdings zeigen Ergebnisse des UBA-Kläranlagen-Monitorings (UBA 2020), dass zum Beispiel Nickelkonzentrationen in Kläranlagenabläufen den Geringfügigkeitsschwellenwert (GFS-Wert) für Grundwasser von $7 \mu \mathrm{~g} / \mathrm{l}$ überschreiten können. Eine Gefährdung des Grundwassers wäre dann gegeben, wenn im Rahmen einer Wasserwiederverwendung eine Stoffverlagerung in das Grundwasser wahrscheinlich erscheint. Bei anderen untersuchten Schwermetallen (Blei, Cadmium, Quecksilber) sind ebenfalls Überschreitungen nicht auszuschließen. — printed p.27', verification_note='md-verified 2026-09-05 (§4.3.6 Schwermetalle, printed p.27 derived) [VC]', verified_at=now() where id='b1d23ef2-a68b-4bb9-b67f-01f9c69e44c1' and verification_status not in ('verified_against_standard','corrected');
-- gefahr_pfas
update public.fields set verification_status='verified_against_standard', verification_quote='Darüber hinaus ist aufgrund des weitverbreiteten Einsatzes und der toxikologischen Relevanz insbesondere Vorsorge zu treffen, dass per- und polyfluorierte Alkylsubstanzen (PFAS) eine Wasserwiederverwendung nicht beeinträchtigen. Hierzu wurde aufbauend auf der EU-Trinkwasserrichtlinie (Richtline (EU) 2020/2184) ein vorsorgeorientierter Beurteilungswert der Summe von 20 PFAS (Summe PFAS-20) von weniger als $100 \mathrm{ng} / \mathrm{l}$ für das aufbereitete Wasser für die erwartete Bundes-WasserWVVO empfohlen (LAWA 2022, UBA 2024). Im Rahmen der Risikocharakterisierung sollte das Einzugsgebiet der Kläranlage auf mögliche PFAS-Einträge bewertet werden — printed p.26–27', verification_note='md-verified 2026-09-05 (§4.3.4 PFAS paragraph, printed p.26–27 derived — between Tab. 3 p.26 and §4.3.5 p.27) [VC] — "Richtline" is the md''s own typo', verified_at=now() where id='5224d52c-7a90-4e4b-8266-75646f1f928b' and verification_status not in ('verified_against_standard','corrected');
-- gefahr_organische_spurenstoffe
update public.fields set verification_status='verified_against_standard', verification_quote='Eine mechanisch-biologische Abwasserbehandlung ist somit nicht ausreichend, um eine weitgehende Entfernung organischer Spurenstoffe zu gewährleisten (PINNEKAMP et al. 2010, SALVESON et al. 2012, GÜnthert \& RÖDel 2013, HÜBNER et al. 2023). Daher ist im Rahmen der Wasserwiederverwendung durch entsprechende Maßnahmen sicherzustellen, dass bei einem nachgewiesenen oder erwarteten erhöhten Risiko vorhandene Spurenstoffe keine Gefährdung für Umwelt und Gesundheit darstellen. | Da hier eine Exposition zu vermeiden ist, muss die Gefahrenanalyse gerade organische Spurenstoffe mit folgenden Eigenschaften umfassen, die sich am Vorschlag neuer Gefahrenklassen der ECHA (Delegierte Verordnung (EU) 2024/1765) orientieren: — printed p.25–26 / p.66', verification_note='md-verified 2026-09-05 (§4.3.4; §6.3.3, printed p.25–26 / p.66 derived) [VC]', verified_at=now() where id='963e6fcc-7be5-4633-b43d-f93066f3575c' and verification_status not in ('verified_against_standard','corrected');
-- gefahr_salze
update public.fields set verification_status='verified_against_standard', verification_quote='In Deutschland wird der Einsatz von aufbereitetem Wasser für die Bewässerung in Bezug auf den Salzgehalt, gemessen als elektrische Leitfähigkeit, als unproblematisch angesehen. Ein Gefährdungspotenzial besteht nur bei deutlich erhöhten Salzgehalten, die typischerweise in kommunalen Abwässern nicht auftreten, vor allem für die Schutzgüter Boden und Pflanze, wobei die pflanzenspezifische Salzverträglichkeit und Salztoleranz wichtige Einflussgrößen sind. — printed p.25', verification_note='md-verified 2026-09-05 (§4.3.2 Salze und ihre Ionen, printed p.25 derived) [VC]', verified_at=now() where id='c8211c89-a5fc-4132-9019-f7b86d0931cd' and verification_status not in ('verified_against_standard','corrected');
-- gefahr_mikroplastik
update public.fields set verification_status='verified_against_standard', verification_quote='Insbesondere beim Einsatz von Filtrationsverfahren, wie sie für die Wassergüteklassen $A$ bis $C$ gemäß Tabelle 5 vorgesehen sind, wird aufgrund der hohen Elimination das Risiko einer Freisetzung von Mikroplastik als gering eingestuft. | Im Sinne des Vorsorgeprinzips ist allerdings eine Minimierung der Einträge in die Umwelt anzustreben. — printed p.28', verification_note='md-verified 2026-09-05 (§4.4 Mikroplastik, printed p.28 derived) [VC]', verified_at=now() where id='8dd5da76-19c0-4d3b-8912-448da07a09e1' and verification_status not in ('verified_against_standard','corrected');
-- k_bio
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 1 (fortgesetzt) | $k_{\text {bio }}$ & biologischer Abbau | Tabelle 3: Gruppeneinteilung untersuchter organischer Spurenstoffe gemäß ihrem Rückhalt aufgrund von Sorption und biologischem Abbau im Belebungsverfahren | Nicht relevanter biologischer Abbau | $k_{\text {bio }}<0,1 \mathrm{l} /(\mathrm{g}$ TS ⋅ d) | Mäßiger biologischer Abbau | $0,1<k_{\text {bio }}<10 \mathrm{l} /(\mathrm{g} \mathrm{TS} \cdot \mathrm{d})$ | Guter biologischer Abbau | $k_{\text {bio }}>10,0 \mathrm{l} /(\mathrm{g}$ TS ⋅ d) — printed p.17 / p.26', verification_note='md-verified 2026-09-05 (Tab. 1 §2.2; Tab. 3 §4.3.4, printed p.17 / p.26 derived) [VC] — UNIT FINDING: the md prints k_bio in l/(g TS · d), the field carries 1/d (see STAGED S-7)', verified_at=now() where id='319a7c33-ca02-4615-8b5d-7a4d9599d16a' and verification_status not in ('verified_against_standard','corrected');
-- ammonium_value
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle B.1: Liste empfohlener Leitsubstanzen für die Abschätzung betroffener Schutzgüter und Expositionswege für ein Wasserwiederverwendungssystem | Anorganische Stoffe | Ammonium ( $\mathrm{NH}_{4}{ }^{+}$) & & & & & $<3 \mathrm{mg} / \mathrm{l}^{(b)}$ & & & $0,5 \mathrm{mg} / \mathrm{l}$ & & & & — printed p.97', verification_note='md-verified 2026-09-05 (Tab. B.1 Anhang B, printed p.97 derived) [VC] — columns: <3 mg/l = Schwellenwert Tränke/Futtermittel (b), 0,5 mg/l = GrwV', verified_at=now() where id='2662df4c-5e92-47fa-a566-ca8cc1555f48' and verification_status not in ('verified_against_standard','corrected');
-- kalium_value
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle B.1: Liste empfohlener Leitsubstanzen für die Abschätzung betroffener Schutzgüter und Expositionswege für ein Wasserwiederverwendungssystem | Kalium & & & $\leqslant 200 \mathrm{mg} / \mathrm{l}$ & & $<250 \mathrm{mg} / \mathrm{l}^{(b)}$ & & & & & & & — printed p.97', verification_note='md-verified 2026-09-05 (Tab. B.1 Anhang B, printed p.97 derived) [VC] — ≤200 mg/l = Toleranzbereich TLL, <250 mg/l = Schwellenwert Tränke (b)', verified_at=now() where id='1a314a45-4500-426d-afe7-8eb47a695989' and verification_status not in ('verified_against_standard','corrected');
-- natrium_value
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle B.1: Liste empfohlener Leitsubstanzen für die Abschätzung betroffener Schutzgüter und Expositionswege für ein Wasserwiederverwendungssystem | Natrium & & & $\leqslant 100 \mathrm{mg} / \mathrm{l}$ & & $<250 \mathrm{mg} / /^{(b)}$ & & & & & & & — printed p.97', verification_note='md-verified 2026-09-05 (Tab. B.1 Anhang B, printed p.97 derived) [VC] — ≤100 mg/l = Toleranzbereich TLL, <250 mg/l = Schwellenwert Tränke (b); "mg / /" is the md''s OCR for mg/l', verified_at=now() where id='250c4114-6298-4bd7-84a0-0acfc2ff6cbe' and verification_status not in ('verified_against_standard','corrected');
-- chlorid_value
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle B.1: Liste empfohlener Leitsubstanzen für die Abschätzung betroffener Schutzgüter und Expositionswege für ein Wasserwiederverwendungssystem | Chlorid & je nach Pflanze $70 \mathrm{mg} / \mathrm{l}-280 \mathrm{mg} / \mathrm{l}$ & & je nach Empfindlichkeit der Pflanze $250 / 500 \mathrm{mg} / \mathrm{l}$ & & $<250 \mathrm{mg} / \mathrm{l}^{(b)}$ & & & $250 \mathrm{mg} / \mathrm{l}$ & $250 \mathrm{mg} / \mathrm{l}$ & & & — printed p.97', verification_note='md-verified 2026-09-05 (Tab. B.1 Anhang B, printed p.97 derived) [VC] — plant-dependent RANGE (SR-2): DIN 19684-10 70–280 mg/l, TLL 250/500, Tränke <250, GrwV 250, GFS 250', verified_at=now() where id='2176c0ac-a311-4df9-8161-23d52f13fd17' and verification_status not in ('verified_against_standard','corrected');
-- fluorid_value
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle B.1: Liste empfohlener Leitsubstanzen für die Abschätzung betroffener Schutzgüter und Expositionswege für ein Wasserwiederverwendungssystem | Fluorid & & & & & $<1,5 \mathrm{mg} / /^{(\mathrm{b})}$; $30 \mathrm{mg} / \mathrm{kg}$ $3000 \mathrm{mg} / \mathrm{kg}^{\text {(c) }}$ & & & & $900 \mu \mathrm{~g} / \mathrm{l}$ & & & — printed p.97', verification_note='md-verified 2026-09-05 (Tab. B.1 Anhang B, printed p.97 derived) [VC] — <1,5 mg/l = Tränke (b), 30/3000 mg/kg = Futtermittel (c), 900 µg/l = LAWA GFS', verified_at=now() where id='80c8aa22-35d0-410f-8f44-370380f94ec6' and verification_status not in ('verified_against_standard','corrected');
-- gesamtphosphor_value
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle B.1: Liste empfohlener Leitsubstanzen für die Abschätzung betroffener Schutzgüter und Expositionswege für ein Wasserwiederverwendungssystem | Gesamtphosphor & & & & & & & & & & & & | Die bei der Bewässerung ausgebrachten Nährstofffrachten müssen aber im Rahmen der Düngeplanung berücksichtigt werden (siehe Merkblatt DWA-M 1200-3). — printed p.97 / p.66', verification_note='md-verified 2026-09-05 (Tab. B.1 Anhang B; §6.3.3, printed p.97 / p.66 derived) [VC] — CAVEAT: Tab. B.1 lists Gesamtphosphor as a Leitsubstanz with NO numeric threshold in any column; the field is a monitoring input only', verified_at=now() where id='4eaf6b9f-59ab-4d84-9b66-a12a6459c58e' and verification_status not in ('verified_against_standard','corrected');


-- ######################## M12001-07 · Risikobewertung und Restrisiko (KRM 5) ########################
-- eintrittswahrscheinlichkeit
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 21: Eintrittswahrscheinlichkeit einer Gefahr (Quelle: angelehnt an ISO 20426:2018) | Niveau & Eintrittswahrscheinlichkeit & Beispielbeschreibungen | A & Selten & Ist bisher noch nicht aufgetreten, und es ist fast sicher ausgeschlossen, dass es in einer überschaubaren Zeitspanne eintritt | B & Unwahrscheinlich & Ist bisher noch nicht aufgetreten, aber könnte bei außergewöhnlichen Umständen in einer überschaubaren Zeitspanne eintreten | C & Möglich & | D & Wahrscheinlich & | E & Sehr gewiss & Wurde bisher wiederholt beobachtet und/oder wird mit hoher Gewissheit unter allen Umständen in einer überschaubaren Zeitspanne eintreten — printed p.69', verification_note='md-verified 2026-09-05 (Tab. 21 §6.3.4, printed p.69 derived) [VC] — enum A–E matches the five printed levels', verified_at=now() where id='9483e737-db50-403c-9d13-4ad1e572c5f9' and verification_status not in ('verified_against_standard','corrected');
-- schadensausmass
