update public.fields set verification_status='verified_against_standard', verification_quote='Die Prüfung, ob für ausgewählte Schutzgüter und Expositionswege eine Beeinträchtigung zu besorgen ist, erfolgt mithilfe des Risikomanagementplans durch die zuständige Behörde. Die im Risikomanagementplan festgelegten, verbindlichen Regelungen müssen von den verantwortlichen Akteuren umgesetzt werden, da er zentrales Element der Aufbereitungsgenehmigung und Aufbringungserlaubnis ist (siehe Abschnitt 7). — printed p.41', verification_note='md-verified 2026-09-05 (§6.1, printed p.41 derived) [VC] — CAVEAT: the attestation checkbox is EKOWAI''s workflow construct for gate CR-016; the quoted sentence is the obligation it attests (the check is the authority''s, not the engineer''s) — the sentence sits in §6.1, not 6.3.2/6.4 (STAGED S-3)', verified_at=now() where id='a916f88b-f0dd-41ff-a825-6e0ec317a922' and verification_status not in ('verified_against_standard','corrected');
