update public.fields set verification_status='verified_against_standard', verification_quote='Zudem wird ein Orientierungswert von $0,1 \mu \mathrm{~g} / \mathrm{l}$ für die Summe von 20 per- und polyfluorierten Alkylsubstanzen (Summe PFAS-20) in Anlehnung an die novellierte EU-Trinkwasserrichtlinie (Richtlinie (EU) 2020/2184) bzw. Trinkwasserverordnung im aufbereiteten Wasser erwartet. | In allen Fällen muss regelmäßig nachgewiesen werden, dass der Beurteilungswert für die Summe der PFAS-20 von $0,10 \mu \mathrm{~g} / \mathrm{l}$ sicher eingehalten werden kann. | Kategorie 3: Vorsorgescreening | Summe PFAS-20<100 ng/l — printed p.33 / p.66–67 / p.67', verification_note='md-verified 2026-09-05 (§5.2; §6.3.3; Tab. 19, printed p.33 / p.66–67 / p.67 derived) [VC] — 0,1 µg/l = 100 ng/l; field unit ng/l consistent', verified_at=now() where id='2c40ae6b-8e6e-49ab-806f-082f1205e41e' and verification_status not in ('verified_against_standard','corrected');
