-- spurenstoffentfernung_szenario
update public.fields set verification_status='verified_against_standard', verification_quote='Auf der Grundlage des erstellten Risikomanagementplans können für die Inbetriebnahme und den Regelbetrieb der Wasseraufbereitung bei der Wasserwiederverwendung zwei Anwendungsszenarien unterschieden werden (Bild 6). Dort wo ein erhöhtes Risiko durch bspw. organische Spurenstoffe durch zusätzliche technische Barrieren minimiert wird (Szenario I), erfolgt ein regelmäßiger Nachweis der Entfernungsleistung durch ein Monitoringprogramm für ausgewählte und prozessspezifische Indikatorchemikalien (Tabelle 19). | Dort wo gemäß der Risikobewertung keine zusätzliche Aufbereitung (gezielte Spurenstoffelimination) nötig ist (Szenario II), ist keine regelmäßige Messung von organischen Spurenstoffen erforderlich. — printed p.66–67', verification_note='md-verified 2026-09-05 (§6.3.3 "Gefahren durch chemische Wasserinhaltsstoffe" + Bild 6 p.67, printed p.66–67 derived) [VC] — clause_reference says §6.6.1; the text sits in §6.3.3 (STAGED S-1)', verified_at=now() where id='c59e5d6d-6154-4cc9-a601-6ef10e09f1c9' and verification_status not in ('verified_against_standard','corrected');
-- indikatorchemikalien_kat2
