update public.fields set verification_status='verified_against_standard', verification_quote='f）Gemäß DWA（2023b）．Bei Polstofffiltern，Mikrosieben und Raumfiltern sollten die Trübungswerte im filtrierten Wasser keinen der folgenden Werte überschreiten：Ein Durchschnittswert von 2 NTU innerhalb eines Zeitraums von $24 \mathrm{~h}, 5 \mathrm{NTU}$ in mehr als $5 \%$ der Zeit innerhalb eines Zeitraums von 24 h und 10 NTU zu keiner Zeit． | Wird die Filtration durch Membranverfahren gewährleistet（Mikrofiltration，Ultrafiltration，Nanofiltration， Umkehrosmose），sollten die Trübungswerte im filtrierten Wasser keinen der folgenden Werte überschreiten： $0,2 \mathrm{NTU}$ in mehr als $5 \%$ der Zeit innerhalb eines Zeitraums von 24 h und 0，5 NTU zu keiner Zeit． — printed p.40', verification_note='md-verified 2026-09-05 (Tab. 8 Anm. f), printed p.40 derived) [VC] — enum polstoff/mikrosieb/raumfilter vs. membran/mikrofiltration/ultrafiltration/nanofiltration/umkehrosmose = the two printed filter families', verified_at=now() where id='f59bbbff-7a11-4433-a346-2a0f2da42b59' and verification_status not in ('verified_against_standard','corrected');
