-- aufbereitungsstufen
update public.fields set verification_status='verified_against_standard', verification_quote='Etablierung einer Filtrationsstufe vor der erforderlichen Desinfektionsstufe nicht nur für die Wassergüteklasse A , sondern auch für die Wassergüteklassen B und C . | Zielvorgabe für Aufberei－ tung | Mechanisch－ biologische Behandlung， Filtration， Desinfektion | Dort wo ein erhöhtes Risiko durch bspw. organische Spurenstoffe durch zusätzliche technische Barrieren minimiert wird (Szenario I), erfolgt ein regelmäßiger Nachweis der Entfernungsleistung — printed p.33 / p.39 / p.66', verification_note='md-verified 2026-09-05 (§5.2 bullet 4; Tab. 8 "Zielvorgabe" A/B/C; §6.3.3, printed p.33 / p.39 / p.66 derived) [VC] — Tab. 8 class D = "Mechanisch-biologische Behandlung, Desinfektion" (no filtration); the field is a SINGLE-select while the printed target is a chain of stages (STAGED S-10)', verified_at=now() where id='29115393-e763-4e52-977e-5aa84d7b2761' and verification_status not in ('verified_against_standard','corrected');


-- ######################## M12001-11 · Karenzzeiten und Bewässerungsmethoden ########################
-- schweinefutter_bewertung
update public.fields set verification_status='verified_against_standard', verification_quote='(*) Die EU-WasserWVVO fordert für die Bewässerung von Futter für Schweine, dass durch hinreichende Daten zu belegen ist, dass ein potenzielles Risiko beherrschbar ist. Anmerkung: In der Schweinehaltung wird überwiegend Futter aus Futtermittelmühlen eingesetzt, da nur dieses die kontrollierten Zusammensetzungen der benötigten Nährstoffe aufweist. | Besondere Vorsorgemaßnahmen: | Beherrschbares Risiko bei Schweinefutter ${ }^{(*)}$ — printed p.37–38 / p.34', verification_note='md-verified 2026-09-05 (Tab. 7 Anm. (*); Tab. 7 class A/B-1/C-1 "Besondere Vorsorgemaßnahmen", printed p.37–38 / p.34 derived) [VC]', verified_at=now() where id='d6650cd9-255e-4ae3-9a13-808f2aa739b2' and verification_status not in ('verified_against_standard','corrected');
-- karenzzeit_tage
update public.fields set verification_status='verified_against_standard', verification_quote='Zusätzlich müssen Karenzzeiten zwischen dem letzten Bewässerungsdurchgang und der Ernte bzw. Konservierung eingehalten werden (Tabelle 7). | Bewässerung von Weiden, Grünland oder anderen frischen Feldfutterpflanzen (z. B. Kleegras) mit aufbereitetem Wasser bis maximal 5 Tage vor dem Schnitt oder Weidegang durch nicht laktierendes Vieh ${ }^{\text {al, cl, d) }}$, besser maximal 2 Wochen ${ }^{\text {b) }}$ | Bewässerung von Weiden, Grünland oder anderen frischen Feldfutterpflanzen (z. B. Kleegras) mit aufbereitetem Wasser bis 4 Wochen vor dem Schnitt oder Weidegang durch nicht laktierendes Vieh — printed p.28 / p.36 / p.37', verification_note='md-verified 2026-09-05 (§4.5 "Futtermittelsicherheit"; Tab. 7 C-1 and D, printed p.28 / p.36 / p.37 derived) [VC] — RANGE by class/use (SR-2): C-1 5 d (better 2 weeks), D 4 weeks / 2 weeks / 30 days, A none; the field is the engineer''s explicit selection; no gate compares it to the class minimum (STAGED S-5)', verified_at=now() where id='9bd537dd-3735-452b-a9a3-66dc23129226' and verification_status not in ('verified_against_standard','corrected');
-- emitterabstand_dauerkulturen_cm
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 7 (fortgesetzt) | C-1 | Tropfbewässerung von Dauerkulturen (Hopfen, Obst und Wein), wenn Ernteprodukte mindestens 25 cm Abstand zum Emitter aufweisen ${ }^{\text {cl,d) }}$ | Mikrosprühbewässerung von Dauerkulturen (Hopfen, Obst und Wein), wenn Ernteprodukte mindestens 50 cm Abstand zum Emitter aufweisen ${ }^{\text {cl,d) }}$ — printed p.36', verification_note='md-verified 2026-09-05 (Tab. 7 C-1, printed p.36 derived) [VC] — printed hard limits 25 cm (Tropf) / 50 cm (Mikrosprüh) with NO gate (STAGED S-5)', verified_at=now() where id='9580114d-bf93-4f3b-aee8-bc41549a6ca8' and verification_status not in ('verified_against_standard','corrected');


-- ######################## M12001-12 · Routineüberwachung (KRM 8) ########################
-- beprobung_frequenz_e_coli
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 27: Mindesthäufigkeit der Routineüberwachung von aufbereitetem Wasser (Quelle: in Anlehnung an Anhang I Abschnitt 2b EU-WasserWVVO, Tabelle 3, sowie Bundes-WasserWVVO) | Mindesthäufigkeit der Überwachung | & E. coli & Intestinale Enterokokken & $\mathrm{BSB}_{5}$ & AFS & Trübung & Legionella spp. (falls zutreffend) & Intestinale Nematoden | 1x pro Woche & 1x pro Woche & 1x pro Woche & 1x pro Woche & | D (B-1/B-2) & 1x pro Woche & 1x pro Woche & | & & 2x pro Monat & | 2x pro Monat & - & — printed p.80', verification_note='md-verified 2026-09-05 (Tab. 27 §6.6.2, printed p.80 derived) [VC] — md GAP: the class-column glyphs are lost, "D (B-1/B-2)" is an OCR artefact for "B (B-1/B-2)", and the C-row E. coli cell is empty in the md (PDF to settle; gate CR-007 quotes "Klasse C 2x pro Monat")', verified_at=now() where id='a3b1030c-3040-475e-bbf9-61a5b071f8a4' and verification_status not in ('verified_against_standard','corrected');
-- probenahme_norm
update public.fields set verification_status='verified_against_standard', verification_quote='Die Proben, die verwendet werden, um die Einhaltung der mikrobiologischen Parameter an der Stelle der Einhaltung zu überprüfen, sind gemäß der Norm DIN EN ISO 19458:2006 oder anderen nationalen oder internationalen Normen, die eine gleichwertige Qualität gewährleisten, zu entnehmen. In Tabelle 27 sind die Anforderungen an die Häufigkeit der Beprobung aufgeführt. — printed p.80', verification_note='md-verified 2026-09-05 (§6.6.2, printed p.80 derived) [VC]', verified_at=now() where id='371f6322-59eb-4c2a-be71-b2133db2d809' and verification_status not in ('verified_against_standard','corrected');
-- compliance_quote_pct
update public.fields set verification_status='verified_against_standard', verification_quote='In Anlehnung an die EU-WasserWVVO müssen die vorgegebenen Werte für E. coli, Legionella spp. und intestinale Nematoden in Tabelle 8 in mindestens $90 \%$ der Proben eingehalten werden. Keiner der Werte der Proben darf die maximale Abweichungsgrenze von einer $\log _{10}$-Stufe für den vorgegebenen Wert für E. coli und Legionella spp. und $100 \%$ des vorgegebenen Werts für intestinale Nematoden überschreiten. | Die vorgegebenen Werte für $\mathrm{BSB}_{5}$, AFS und Trübung bei Güteklasse A bis C müssen in mindestens $90 \%$ der Proben eingehalten werden. — printed p.34', verification_note='md-verified 2026-09-05 (§5.2 compliance paragraphs, printed p.34 derived) [VC] — gate CR-008 enforces ≥ 90 %', verified_at=now() where id='39e745a2-dafd-441b-8651-25f2b6007b5b' and verification_status not in ('verified_against_standard','corrected');
-- validierungs_compliance_pct
update public.fields set verification_status='verified_against_standard', verification_quote='Für die Wassergüteklasse A müssen mindestens $90 \%$, für die Wassergüteklassen B-1 und C-1 mindestens $50 \%$ der Validierungsproben die Leistungsziele erreichen oder übersteigen (Näheres siehe Merkblatt DWA-M 1200-2). | b）Gemäß LAWA（2022）sollten die Leistungsziele neben Güteklasse A auch für die Güteklassen B－1 und C－1 gelten． Klasse A：Mindestens 90 ％der Proben müssen die Leistungsziele erreichen．Klassen B－1／C－1：Mindestens 50 ％ der Proben müssen die Leistungsziele erreichen． — printed p.34 / p.40', verification_note='md-verified 2026-09-05 (§5.2; Tab. 8 Anm. b), printed p.34 / p.40 derived) [VC] — class-dependent minimum (A 90 %, B-1/C-1 50 %) with NO gate (STAGED S-5); only meaningful for A/B-1/C-1 (STAGED S-8)', verified_at=now() where id='f7043885-c9ce-49c3-811d-f2bca5d0396e' and verification_status not in ('verified_against_standard','corrected');
-- abweichung_log10_max
