-- gfs_orientierung
update public.fields set verification_status='verified_against_standard', verification_quote='Die Überprüfung und Einordnung der gemessenen Werte sollte sich im Rahmen des Risikomanagements an den Geringfügigkeitsschwellenwerten (GFS, LAWA 2016) für das Grundwasser bzw. an den Vorgaben der BBodSchV sowie der Richtlinie 2002/32/EG über unerwünschte Stoffe in der Tierernährung orientieren. Zugleich ist die Verordnung (EU) 2023/915 für Höchstgrenzen von Kontaminanten in Lebensmitteln zu beachten. — printed p.81', verification_note='md-verified 2026-09-05 (§6.6.3 Umweltmonitoring, printed p.81 derived) [VC] — "sollte" (STAGED S-8 required-flag)', verified_at=now() where id='9b91d7d1-71b2-4696-81e4-2883de736925' and verification_status not in ('verified_against_standard','corrected');
