update public.fields set verification_status='verified_against_standard', verification_quote='Zusätzlich sind die in BBodSchV Anlage 1 Tabelle 3 genannten zulässigen zusätzlichen jährlichen Schadstofffrachten zu berücksichtigen. Der Eintrag über aufbereitetes Wasser sollte maximal einem Drittel der dort genannten Frachten entsprechen (LAWA 2022). | Die in Anlage 1 Tabelle 3 BBodSchV genannten zulässigen zusätzlichen jährlichen Schadstofffrachten (Metalle; Benzo(a)pyren) dürfen maximal zu einem Drittel mit dem aufbereiteten Wasser ausgebracht werden. — printed p.28 / p.59', verification_note='md-verified 2026-09-05 (§4.5 "Bodenvorsorge"; §6.3.2.2 "Boden", printed p.28 / p.59 derived) [VC] — §6.3.2.2 says "dürfen maximal" (hard) while §4.5 says "sollte"; NO gate on ≤ 1/3 (STAGED S-5)', verified_at=now() where id='17e2ae53-e5b3-48c8-8dff-fec7dcdee215' and verification_status not in ('verified_against_standard','corrected');
