update public.fields set verification_status='verified_against_standard', verification_quote='Die Auswahl der Messstellen ist darzustellen und zu begründen. Eine jährliche Berichtspflicht wird empfohlen. | Weitere Anforderungen an die Eigenüberwachung ergeben sich aus dem Risikomanagementplan und sind Bestandteil der Genehmigung. Diese können die Vorlage eines jährlichen Berichts über die Tätigkeiten zur Aufbereitung, Speicherung und Verteilung des aufbereiteten Wassers an die zuständige Behörde beinhalten. — printed p.81 / p.80', verification_note='md-verified 2026-09-05 (§6.6.3; §6.6.2, printed p.81 / p.80 derived) [VC] — "empfohlen"; gate CR-020 is warn (correct)', verified_at=now() where id='a466f1b1-a189-4b3c-b34c-2ec4bdf45ec0' and verification_status not in ('verified_against_standard','corrected');
