update public.fields set verification_status='verified_against_standard', verification_quote='Vor Inbetriebnahme der Wasserwiederverwendung sollte darüber hinaus die Hintergrundbelastung des bewässerten Bodens ermittelt und dokumentiert werden. | Die Hintergrundbelastung des Bodens mit anorganischen sowie organischen Schadstoffen leinschließlich Summe PFAS-20) sollte vor der Inbetriebnahme einer Wasserwiederverwendung ermittelt | und dokumentiert werden. Die Untersuchungen sind entsprechend Anlage 3 Tabellen 4, 5 BBodSchV oder dazu gleichwertigen Verfahren nach §§ 24, 25 BBodSchV durchzuführen. — printed p.81 / p.59–60', verification_note='md-verified 2026-09-05 (§6.6.3; §6.3.2.2 "Boden", printed p.81 / p.59–60 derived) [VC] — "sollte" → gate CR-009 warn (correct); required=true on a "sollte" (STAGED S-8); "leinschließlich" is the md OCR for "(einschließlich"', verified_at=now() where id='df696c7f-3c86-43b6-81ee-856b9d4435a3' and verification_status not in ('verified_against_standard','corrected');
