-- ######################## M12001-14 · Störfallmanagement und Koordinierung (KRM 10/11) ########################
-- notfall_verteiler_existent
update public.fields set verification_status='verified_against_standard', verification_quote='Einbeziehung bei Vor-/Störfällen | Alle am Wasserwiederverwendungssystem beteiligten Akteure sind verpflichtet, einen relevanten Vor-/Störfall sofort zu melden: | Die Einrichtung von Notfall-Verteilern, zum Beispiel als E-Mail-Verteiler mit Rufnummernlisten, wird empfohlen, mit denen jede verantwortliche Partei entsprechend der Fallkonstellation die anderen verantwortlichen Parteien informieren kann. — printed p.52', verification_note='md-verified 2026-09-05 (§6.2.2 "Einbeziehung bei Vor-/Störfällen", printed p.52 derived) [VC] — "wird empfohlen" yet gate CR-017 BLOCKS on it (STAGED S-4); required=true on a recommendation (STAGED S-8)', verified_at=now() where id='5b8e47e5-a3c2-459e-9425-421eebf8dad0' and verification_status not in ('verified_against_standard','corrected');
-- stoerfall_meldewege
update public.fields set verification_status='verified_against_standard', verification_quote='Für verschiedene Fallkonstellationen von Vor-/Störfällen sind im RMP Meldewege und Gegenmaßnahmen festzulegen. | Alle Akteure, die zur Exposition der Schadstoffe beitragen können oder selbst einem Expositionsrisiko ausgesetzt sind, müssen sofort durch die den Vor-/Störfall auslösende Partei auf möglichst kurzem Weg informiert werden. | Die zuständige Behörde ist sofort zu informieren und bindet weitere relevante Fachbehörden ein, wie zum Beispiel die Gesundheits- oder Naturschutzbehörde. | Festlegung von Kommunikationsplänen im Vor- bzw. Störfall (einschließlich interner und externer Kommunikation). — printed p.52 / p.82', verification_note='md-verified 2026-09-05 (§6.2.2 "Einbeziehung bei Vor-/Störfällen"; §6.7, printed p.52 / p.82 derived) [VC] — the "sind festzulegen" sentence sits in §6.2.2, not §6.7 as tagged (STAGED S-1)', verified_at=now() where id='465205f0-52f7-425b-9843-ad4cb7017ca6' and verification_status not in ('verified_against_standard','corrected');


-- ######################## M12001-15 · Aufbereitungsgenehmigung (§61b WHG) ########################
-- genehmigung_aktualisierung_trigger
update public.fields set verification_status='verified_against_standard', verification_quote='Eine Aktualisierung der Genehmigung ist gemäß Artikel 6 Absatz 6 EU-WasserWVVO mindestens erforderlich bei | wesentlicher Veränderung der Kapazität; | Modernisierung der Ausstattung; | Einsatz neuer Ausstattung oder Verfahren; | Veränderungen der klimatischen oder sonstigen Bedingungen, die den ökologischen Zustand von Oberflächenwasserkörpern erheblich beeinflussen. — printed p.85', verification_note='md-verified 2026-09-05 (§7.2, printed p.85 derived) [VC] — four printed triggers; free-text field (guideline options → selection ruling 2026-08-01 applies: STAGED S-10)', verified_at=now() where id='3de488ce-5f0b-4cad-a6d0-db19863dc880' and verification_status not in ('verified_against_standard','corrected');
-- rmp_aktualisierungs_intervall_jahre
update public.fields set verification_status='verified_against_standard', verification_quote='Die Etablierung und Fortführung eines RMP ist als ein mehrstufiger, iterativer Prozess zu verstehen, bei dem die verantwortlichen Akteure für die Laufzeit eines Vorhabens zur Wiederverwendung in einem regelmäßigen Austausch stehen und, wo erforderlich, den RMP entsprechend ergänzen. Der RMP sollte unabhängig von Veränderungen im Betrieb alle 6 Jahre aktualisiert werden. | Daher ist die vorgenommene umfassende Gefahrenbetrachtung chemischer Inhaltsstoffe für ein Vorhaben zur Wasserwiederverwendung regelmäßig zu wiederholen und entsprechend zu dokumentieren, mindestens im Zuge der Revision des Risikomanagementplans alle 6 Jahre, besser jedoch häufiger, sowie bei einer signifikanten Veränderung der Indirekteinleitungen. — printed p.42–43 / p.66', verification_note='md-verified 2026-09-05 (§6.1; §6.3.3, printed p.42–43 / p.66 derived) [VC] — "sollte … alle 6 Jahre"; gate CR-012 meant to check this has no condition (STAGED S-2); required=true on a "sollte" (STAGED S-8)', verified_at=now() where id='8aa5577f-1a3d-405f-bc6b-782b57aab4d4' and verification_status not in ('verified_against_standard','corrected');
-- attest_m12001_15_cr_019
update public.fields set verification_status='verified_against_standard', verification_quote='Die Unterlagen, die den Genehmigungs- bzw. Erlaubnisanträgen in jedem Fall beiliegen sollten, sind in den folgenden Unterabschnitten aufgeführt. Entsprechend den jeweiligen Landesregelungen kann die zuständige Behörde im Einzelfall die Vorlage weiterer projektspezifischer Unterlagen verlangen. Die erforderlichen Antragsunterlagen und deren Inhalt sind vorab mit der zuständigen Behörde abzustimmen. — printed p.84', verification_note='md-verified 2026-09-05 (§7.1, printed p.84 derived) [VC] — CAVEAT: the attestation checkbox is EKOWAI''s workflow construct for gate CR-019; the quoted sentences are the obligation it attests (the gate quote prints them in reverse order)', verified_at=now() where id='e41a1089-ea20-43f2-8829-40e45db92084' and verification_status not in ('verified_against_standard','corrected');
-- genehmigungs_inhalt_komplett
update public.fields set verification_status='verified_against_standard', verification_quote='Die Aufbereitungsgenehmigung muss entsprechend Artikel 6 Absatz 3 EU-WasserWVVO folgende Inhalte umfassen: | Aussagen zu der Güteklasse des aufbereiteten Wassers und dem Verwendungszweck bzw. den Verwendungszwecken (Kulturen, Nutzungen etc.), für den bzw. die das aufbereitete Wasser gemäß Anhang I zu genehmigen ist, den potenziellen Verbrauchsstellen linkl. eines Flächenverzeichnisses der zu bewässernden Flächen), den Aufbereitungseinrichtungen und der geschätzten jährlichen Menge des aufzubereitenden Wassers, dem Zustand sowie der Nutzung der Flächen einschließlich der Bewässerungsmethode; | Nennung der festgelegten Mindestanforderungen an die Wasserqualität; | Gültigkeitszeitraum der Genehmigung; | Der RMP ist Bestandteil der Genehmigung. — printed p.84', verification_note='md-verified 2026-09-05 (§7.2 Art. 6 Abs. 3 list, printed p.84 derived) [VC] — "muss"; gate CR-010 block (correct); "linkl." is the md OCR for "(inkl."', verified_at=now() where id='606007c3-98ac-4724-8a04-1b06b52daee0' and verification_status not in ('verified_against_standard','corrected');


-- ######################## M12001-16 · Aufbringungserlaubnis (§61c / §8 WHG) ########################
-- aufbringungserlaubnis_antragsteller
update public.fields set verification_status='verified_against_standard', verification_quote='Entsprechend § 8 Absatz 1 WHG in Verbindung mit § 9 Absatz 2 Nummer 5 WHG (BMUV 2024) beantragt der Endnutzer für die Bewässerung mit aufbereitetem Wasser eine Erlaubnis. Dem Antrag ist der RMP beizufügen. | Sofern nicht schon im RMP enthalten, werden folgende Antragsunterlagen für die Aufbringungserlaubnis (Antragsteller = Endnutzer) empfohlen: — printed p.87', verification_note='md-verified 2026-09-05 (§7.4 Aufbringungserlaubnis, printed p.87 derived) [VC]', verified_at=now() where id='f78ec601-215b-456e-bd94-aa48581033a0' and verification_status not in ('verified_against_standard','corrected');
-- flaechenverzeichnis_vorhanden
update public.fields set verification_status='verified_against_standard', verification_quote='den potenziellen Verbrauchsstellen linkl. eines Flächenverzeichnisses der zu bewässernden Flächen), den Aufbereitungseinrichtungen und der geschätzten jährlichen Menge des aufzubereitenden Wassers, dem Zustand sowie der Nutzung der Flächen einschließlich der Bewässerungsmethode; | Karte der potenziell zu bewässernden Flächen und Verbrauchsstellen des aufbereiteten Wassers. | Führen eines Registers, das die Flächen enthält, auf die das aufbereitete Wasser aufgebracht wurde, sowie die Kulturen und die Bewässerungsmenge und Bewässerungsmethode | Eine Aktualisierung der Aufbringungserlaubnis ist mindestens erforderlich bei: | Veränderung der Bewässerungsflächen; — printed p.84 / p.86 / p.50 / p.87', verification_note='md-verified 2026-09-05 (§7.2 Art. 6 Abs. 3; §7.2 Antragsunterlagen; Tab. 10 Endnutzer; §7.4, printed p.84 / p.86 / p.50 / p.87 derived) [VC] — enforced twice (CR-011 ws 16 and CR-015 ws 15; STAGED S-9)', verified_at=now() where id='587ec18e-6647-48d2-b615-f7f4bd9ad648' and verification_status not in ('verified_against_standard','corrected');


-- ######################## M12001-18 · Wirtschaftlichkeit und Finanzierung ########################
-- gebuehrenfaehigkeit_aufbereitung
update public.fields set verification_status='verified_against_standard', verification_quote='Die Verwendung von aufbereitetem Wasser zählt entsprechend WHG nicht zur Abwasserbeseitigung. Kosten für eine weitergehende Wasseraufbereitung, wie zum Beispiel eine Desinfektion oder gezielte Elimination von Spurenstoffen, die der Wasserwiederverwendung dienen, sind daher nicht gebührenfähig und müssen somit anderweitig finanziert werden. Mit zunehmenden Anforderungen, zum Beispiel bei Einleitung in ausgewiesene Badegewässer, werden auch die Kosten für diese Verfahrenseinheiten gebührenfähig. — printed p.89', verification_note='md-verified 2026-09-05 (§8.2 Finanzierung, printed p.89 derived) [VC]', verified_at=now() where id='0574e09b-cc44-4949-bbd7-9cdebeb9647e' and verification_status not in ('verified_against_standard','corrected');


