-- beschilderung_urbane_flaechen
update public.fields set verification_status='verified_against_standard', verification_quote='Einhaltung der Vorsorgemaßnahmen gemäß Bundes-WasserWVVO (nach Anhang II, Teil C) bzw. Vorsorgemaßnahmen bei der Bewässerung urbaner Grünflächen (z. B. Beschilderung) | Beschilderung an Bewässerungsflächen, die darauf hinweisen, dass aufbereitetes und nicht als Trinkwasser geeignetes Wasser verwendet wird (Hinweisschilder, ggf. Schilder mit Betretungsverbot bei laufender Bewässerung), | die Beschilderung an Bewässerungsflächen. — printed p.50 / p.78 / p.74', verification_note='md-verified 2026-09-05 (Tab. 10 Endnutzer; §6.5.5; §6.5.1 Anhang-II-Teil-C list, printed p.50 / p.78 / p.74 derived) [VC]', verified_at=now() where id='4fc4f0c0-2b1c-4bb2-aa71-617318cdc8db' and verification_status not in ('verified_against_standard','corrected');


-- ######################## M12001-20 · RMP-Zusammenstellung und Aktualisierung ########################
-- (alle_genehmigungen: exempt, see the grouped statement under M12001-01)
-- rmp_vollstaendig
update public.fields set verification_status='verified_against_standard', verification_quote='Zu diesem Zweck schreibt die EU-WasserWVVO die Erstellung eines Risikomanagementplans (RMP) für die Wasserwiederverwendung verbindlich vor. Auch für urbane Anwendungen einer Wasserwiederverwendung, die bisher nicht in der EU-WasserWVVO geregelt sind, empfiehlt dieses Merkblatt eine entsprechende Risikocharakterisierung und Erstellung eines RMP. | Grundlage für jeden Genehmigungsantrag ist der Risikomanagementplan (RMP; siehe Abschnitt 6). | Der RMP ist Bestandteil der Genehmigung. — printed p.41 / p.83 / p.84', verification_note='md-verified 2026-09-05 (§6.1; §7.1; §7.2, printed p.41 / p.83 / p.84 derived) [VC] — mandatory for agricultural use, "empfiehlt" for urban-only use (gate CR-002 severity note, STAGED S-4)', verified_at=now() where id='40f2cdae-191a-4cb2-a550-944bd5793a76' and verification_status not in ('verified_against_standard','corrected');
-- rmp_letzte_aktualisierung
update public.fields set verification_status='verified_against_standard', verification_quote='Sowohl technische als auch administrative Veränderungen im Betrieb, aber auch neue Erkenntnisse zu Managementmaßnahmen erfordern eine regelmäßige Aktualisierung des RMP für die Wasserwiederverwendung. [...] Der RMP sollte unabhängig von Veränderungen im Betrieb alle 6 Jahre aktualisiert werden. | Durchsicht der Dokumentation auf Plausibilität, Diskussion der Ergebnisse und Festlegungen zur periodischen Revision — printed p.42–43 / p.43', verification_note='md-verified 2026-09-05 (§6.1; Tab. 9 Arbeitshilfe A, printed p.42–43 / p.43 derived) [VC] — CAVEAT: the date itself is an app record; the printed rule is the 6-year revision it is measured against (STAGED S-8 required-flag)', verified_at=now() where id='cb644be5-15fb-4976-8a79-53f1a2d38849' and verification_status not in ('verified_against_standard','corrected');


