-- EQ-001 risikoniveau_ausgangs = lookup(eintrittswahrscheinlichkeit, schadensausmass) (ws 07)
update public.equations set verification_status='verified_against_standard', verification_quote='Aus dem Produkt von Eintrittswahrscheinlichkeit und zu erwartenden Konsequenzen bzw. Schadensausmaß lässt sich das Risikoniveau bestimmen: | Risikoniveau $=$ Eintrittswahrscheinlichkeit × Schadensausmaß | Tabelle 23: Risikomatrix für eine qualitative Risikobewertung (Quelle: angelehnt an ISO 20426:2018) | A - Selten & Sehr niedrig & Sehr niedrig & Niedrig & Niedrig & Moderat | B - Unwahrscheinlich & Sehr niedrig & Niedrig & Niedrig & Moderat & Hoch | C - Möglich & Niedrig & Niedrig & Moderat & Hoch & Hoch | D - Wahrscheinlich & Niedrig & Moderat & Hoch & Hoch & Sehr hoch | E - Sehr gewiss & Moderat & Hoch & Hoch & Sehr hoch & Sehr hoch — printed p.69–70', verification_note='md-verified 2026-09-05 (§6.3.4 + Tab. 23, printed p.69–70 derived) [VC] — the printed "×" is a qualitative matrix product, not arithmetic; the encoded lookup() over Tab. 23 is the faithful form (25 cells checked against the md rows)', verified_at=now() where id='978ac484-ac6c-4611-9a87-359c900b88dc' and verification_status <> 'verified_against_standard';
